<script setup lang="ts">
const props=defineProps<{compact?:boolean}>();const route=useRoute();
const page=computed(()=>props.compact?1:Math.max(1,Number(route.query.page)||1));
const {data,error}=await useFetch<any>('/api/news',{query:computed(()=>({page:page.value,limit:props.compact?3:10}))});
</script>
<template><section v-if="!compact||data?.items?.length||error" class="news-feed"><div class="section-heading"><h2 v-if="compact">Latest news</h2><NuxtLink v-if="compact" to="/news" class="inline-link">All news →</NuxtLink></div><CindorAlert v-if="error" class="portal-alert" tone="danger">News could not be loaded. Please refresh to try again.</CindorAlert><p v-else-if="!data?.items?.length" class="muted">No news yet. Check back for updates.</p><div class="news-cards"><CindorCard v-for="post in data?.items" :key="post.id" class="panel"><time :datetime="new Date(post.published).toISOString()">{{new Date(post.published).toLocaleDateString()}}</time><h3><NuxtLink :to="'/news/'+post.id">{{post.title}}</NuxtLink></h3><p>{{post.excerpt}}</p><NuxtLink :to="'/news/'+post.id" class="inline-link" :aria-label="'Read '+post.title">Read more →</NuxtLink></CindorCard></div><nav v-if="!compact&&data?.total>10" class="actions" aria-label="News pages"><NuxtLink v-if="page>1" class="button" :to="{path:'/news',query:{page:page-1}}">Previous</NuxtLink><span>Page {{page}}</span><NuxtLink v-if="page*10<data.total" class="button" :to="{path:'/news',query:{page:page+1}}">Next</NuxtLink></nav></section></template>
